}

function IsCustomBuilding( entityIndex ){
    var ability_building = Entities.GetAbilityByName( entityIndex, "ability_building")
    var ability_tower = Entities.GetAbilityByName( entityIndex, "ability_tower")
    return (ability_building != -1 || ability_tower != -1)
}

function IsShop1Dummy(entityIndex) {
    var name = Entities.GetUnitName(entityIndex) || ""
    return name.indexOf("npc_dota_auto_cast_dummy") === 0
}

function IsShop1SelectionProxy(entityIndex) {
    var name = Entities.GetUnitName(entityIndex) || ""
    return name === "npc_dota_selection_proxy"
}

function UpdateRangeParticle() {
    var mainSelected = Players.GetLocalPlayerPortraitUnit()
    var range = 0

    if (Entities.IsValidEntity && Entities.IsValidEntity(mainSelected)) {
        if (IsCustomBuilding(mainSelected) && Entities.HasAttackCapability(mainSelected)) {
            range = Entities.GetAttackRange(mainSelected)
        } else if (IsShop1Dummy(mainSelected) || IsShop1SelectionProxy(mainSelected)) {
